-- Atomic per-client rate limits for the public directory Edge Function.
-- Bucket keys are HMACs generated by the Edge Function, so raw IPs and
-- usernames are never stored in this table.
create table if not exists public.directory_rate_limits (
  bucket_key text primary key check (bucket_key ~ '^[a-f0-9]{64}$'),
  window_started_at timestamptz not null,
  request_count integer not null check (request_count > 0)
);

create index if not exists directory_rate_limits_window_idx
  on public.directory_rate_limits (window_started_at);

alter table public.directory_rate_limits enable row level security;
revoke all on public.directory_rate_limits from public, anon, authenticated;
grant select, insert, update, delete on public.directory_rate_limits to service_role;

create or replace function public.consume_directory_rate_limit(
  p_bucket_key text,
  p_limit integer,
  p_window_seconds integer
)
returns table (allowed boolean, retry_after_seconds integer)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_window_started timestamptz;
  v_count integer;
begin
  if p_bucket_key !~ '^[a-f0-9]{64}$'
    or p_limit < 1 or p_limit > 10000
    or p_window_seconds < 1 or p_window_seconds > 86400 then
    raise exception 'Invalid rate limit request';
  end if;

  insert into public.directory_rate_limits as current_bucket
    (bucket_key, window_started_at, request_count)
  values (p_bucket_key, v_now, 1)
  on conflict (bucket_key) do update set
    window_started_at = case
      when current_bucket.window_started_at + make_interval(secs => p_window_seconds) <= v_now then v_now
      else current_bucket.window_started_at
    end,
    request_count = case
      when current_bucket.window_started_at + make_interval(secs => p_window_seconds) <= v_now then 1
      else current_bucket.request_count + 1
    end
  returning current_bucket.window_started_at,
            current_bucket.request_count
  into v_window_started, v_count;

  -- Keep abandoned HMAC buckets bounded without scanning the whole table.
  delete from public.directory_rate_limits
  where bucket_key in (
    select bucket_key from public.directory_rate_limits
    where window_started_at < v_now - interval '1 day'
    order by window_started_at
    limit 100
  );

  return query select
    v_count <= p_limit,
    case when v_count <= p_limit then 0
      else greatest(1, ceil(extract(epoch from (
        v_window_started + make_interval(secs => p_window_seconds) - v_now
      )))::integer)
    end;
end;
$$;

revoke all on function public.consume_directory_rate_limit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.consume_directory_rate_limit(text, integer, integer) to service_role;
